const capabilities = computed(() => environment.value.capabilities || {})
const state = computed(() => ({ READY:'就绪', PAUSED:'已暂停', RUNNING:'运行中', CLOSED:'已结束', INTERRUPTED:'已中断', LOADING:'加载中' }[props.session?.state] || '未连接'))
const position = computed(() => props.scene?.eef?.position)
const last = computed(() => props.session?.last_command)
</script>
