    <div class="position-readout"><span class="readout-label">末端位置 <small>m</small></span><div class="coordinates"><div v-for="(axis,index) in ['X','Y','Z']" :key="axis"><span>{{ axis }}</span><strong>{{ position?.[index]?.toFixed(3) ?? '—' }}</strong></div></div></div>
